import{_ as t,H as a,f as i,i as _}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"测一测 | 高性能检索系统的实战知识，你掌握了多少？","description":"","frontmatter":{},"headers":[{"level":2,"title":"主观题","slug":"主观题","link":"#主观题","children":[]}],"relativePath":"检索技术核心20讲/测一测-高性能检索系统的实战知识，你掌握了多少？.md","filePath":"检索技术核心20讲/测一测-高性能检索系统的实战知识，你掌握了多少？.md","lastUpdated":1779820892000}'),r={name:"检索技术核心20讲/测一测-高性能检索系统的实战知识，你掌握了多少？.md"};function n(l,e,o,s,p,c){return a(),i("div",null,[...e[0]||(e[0]=[_('<h1 id="测一测-高性能检索系统的实战知识-你掌握了多少" tabindex="-1">测一测 | 高性能检索系统的实战知识，你掌握了多少？ <a class="header-anchor" href="#测一测-高性能检索系统的实战知识-你掌握了多少" aria-label="Permalink to &quot;测一测 | 高性能检索系统的实战知识，你掌握了多少？&quot;">​</a></h1><p>你好，我是陈东。欢迎来到进阶实战篇的测试环节！</p><p>在进阶实战篇中，我们针对一些应用中的实际问题，学习了对应的经典解决方案。这其中涉及了很多高级的检索知识，以及一些高性能检索系统的设计思想。这些知识，无论是对你现在的工作来说，还是对你之后自己设计系统、设计应用都会有非常大的帮助。</p><p>那这些知识你都掌握了多少呢？为了让你能检验自己的学习效果，同时也能巩固之前讲过的知识，我特别给你准备了一套测试题。和基础篇的测试一样，题目不多，依然是20道单选题，也同样建议你在30分钟内完成。</p><p>当然，我还为你准备了一道主观题。可以好好想想，利用我们进阶篇学到的知识怎么来解答，最后，希望你能把思考过程和最终答案都写在留言区，我们一起探讨。我会在下周三把解题思路放到评论区，一定要来看啊。</p><p>还等什么，点击下面的按钮开始测试吧！</p><p><a href="http://time.geekbang.org/quiz/intro?act_id=131&amp;exam_id=283" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%A3%80%E7%B4%A2%E6%8A%80%E6%9C%AF%E6%A0%B8%E5%BF%8320%E8%AE%B2/images/232713/28d1be62669b4f3cc01c36466bf811a4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%A3%80%E7%B4%A2%E6%8A%80%E6%9C%AF%E6%A0%B8%E5%BF%8320%E8%AE%B2/images/232713/28d1be62669b4f3cc01c36466bf811a4.png" alt=""></a></a></p><h2 id="主观题" tabindex="-1">主观题 <a class="header-anchor" href="#主观题" aria-label="Permalink to &quot;主观题&quot;">​</a></h2><p>假设有一个移动互联网应用，要实现找到附近具有相同兴趣的人功能。这里面的相同兴趣，指的是具有相同兴趣标签的人。如果一个人身上有多个标签，那只要有一个标签和其他人相同，就算有相同兴趣。</p><p>在这种情况下，我们需要支持以下功能：</p><ol><li>列出附近兴趣相同的人，允许结果为空；</li><li>系统要具备实时性，如果有用户的标签发生变化或者位置发生变化，需要及时在系统中得到体现；</li><li>如果附近兴趣相同的人很多，那么需要将这些人进行排序，需要设计排序方案。</li></ol><p>如果使用我们在进阶实战篇中学到的知识，你会怎么来设计和实现这个功能呢？</p>',12)])])}const f=t(r,[["render",n]]);export{h as __pageData,f as default};
